    Bug 2017853 - Wait for load completion before content checks in browser_ext_contentScripts.js updateMailTabBrowser. r=arschmitz

    The updateMailTabBrowser sub-tests load content into the mail tab via
    tabs.update(). MailE10SUtils.loadURI() does the remoteness switch
    (browser.destroy() + frameloader swap + browser.construct()) synchronously at
    the start of the load, tearing down the browsing context's SpecialPowers actor.
    Because tabs.update() resolves as soon as the load is initiated, signalling the
    tab as ready right afterwards lets checkContent()'s SpecialPowers.spawn() race
    that teardown -> "AbortError: Actor 'SpecialPowers' destroyed before query
    'Spawn' was resolved".

    This implements approach 1 of the two documented in comment 10: have the
    background getTestTab helper wait for tabs.onUpdated status "complete" (which
    fires only after the remoteness switch and the content load) before signalling
    the tab as ready, so the spawn runs against the settled, final browser. Gate on
    status only (not changeInfo.url), since the NoPermissions sub-tests run without
    host permission and never receive url.

    Differential Revision: https://phabricator.services.mozilla.com/D310470

diff --git a/mail/components/extensions/test/browser/browser_ext_contentScripts.js b/mail/components/extensions/test/browser/browser_ext_contentScripts.js
index d1edfd3aa75..3036c27467c 100644
--- a/mail/components/extensions/test/browser/browser_ext_contentScripts.js
+++ b/mail/components/extensions/test/browser/browser_ext_contentScripts.js
@@ -133,10 +133,28 @@ function getBackgoundHelperFunctions() {
         case "createWebExtensionTab":
           return browser.tabs.create({ url: config.url });

-        case "updateMailTabBrowser":
-          return browser.tabs
-            .query({ active: true })
-            .then(tabs => browser.tabs.update(tabs[0].id, { url: config.url }));
+        case "updateMailTabBrowser": {
+          const [activeTab] = await browser.tabs.query({ active: true });
+          // tabs.update() resolves when the load is initiated, not finished.
+          // Loading content into the mail tab swaps its <browser>, so wait for
+          // the load to complete before returning; otherwise the test's
+          // SpecialPowers.spawn can race the swap and hit a destroyed actor.
+          // Gate on status only: the "no permissions" sub-tests run without host
+          // permission, so onUpdated never reports changeInfo.url for them. The
+          // parent's awaitBrowserLoaded() does the chrome-side url check.
+          const loaded = new Promise(resolve => {
+            const listener = (tabId, changeInfo) => {
+              if (tabId == activeTab.id && changeInfo.status == "complete") {
+                browser.tabs.onUpdated.removeListener(listener);
+                resolve();
+              }
+            };
+            browser.tabs.onUpdated.addListener(listener);
+          });
+          await browser.tabs.update(activeTab.id, { url: config.url });
+          await loaded;
+          return browser.tabs.get(activeTab.id);
+        }

         case "createWebExtensionPopup":
           return browser.windows
